"prep-it-international","universityId":"prep-it","program":{"uz":"Ingliz tilidagi IT dasturlari: matematika, fizika va IELTS","ru":"ИТ-программы на английском: математика, физика и IELTS","en":"English-taught IT programmes: Mathematics, Physics and IELTS"},"directionIds":["prep-it-international"],"name":{"uz":"Ingliz tilidagi IT dasturlari: matematika, fizika va IELTS","ru":"ИТ-программы на английском: математика, физика и IELTS","en":"English-taught IT programmes: Mathematics, Physics and IELTS"},"description":{"uz":"Umumiy tayyorgarlik: fanlar quyida körsatilgan rasmiy manbadan olingan. Paket biror universitet bilan rasmiy boğliq emas va uning dasturi emas.","ru":"Общая подготовка: предметы взяты из указанного ниже официального источника. Пакет официально не связан ни с одним университетом и не является его программой.","en":"General preparation: the subjects come from the official source named below. The package is not officially affiliated with any university and is not its programme."},"slots":[{"id":"prep-it-international-s1","label":{"uz":"Matematika","ru":"Математика","en":"Mathematics"},"courseKey":"c-algebra"},{"id":"prep-it-international-s2","label":{"uz":"Fizika","ru":"Физика","en":"Physics"},"courseKey":"c-physics"},{"id":"prep-it-international-s3","label":{"uz":"Ingliz tili (IELTS 5.0 yoki TOEFL iBT 50; sertifikat bölsa şart emas)","ru":"Английский язык (IELTS 5.0 или TOEFL iBT 50; не нужен при наличии сертификата)","en":"English (IELTS 5.0 or TOEFL iBT 50; not needed with a certificate)"},"courseKey":"c-ielts","optional":true}],"admission":{"url":"https://inha.uz/prospective-students/admissions/application-guideline/","academicYear":"2026-2027","checkedOn":"2026-11-03","status":"needs_review","note":"To be confirmed: general preparation, not a programme of one university. INHA’s 2026-2027 guideline asks Mathematics and Physics in its own exam and an English certificate; other English-taught programmes differ, so check yours."},"hasSource":true},{"id":"prep-economics-state","universityId":"prep-economics","program":{"uz":"Iqtisodiyot yönalişlari (davlat testi): matematika va çet tili","ru":"Экономические направления (государственный тест): математика и иностранный язык","en":"Economics directions (state test): Mathematics and a foreign language"},"directionIds":["prep-economics-state"],"name":{"uz":"Iqtisodiyot yönalişlari (davlat testi): matematika va çet tili","ru":"Экономические направления (государственный тест): математика и иностранный язык","en":"Economics directions (state test): Mathematics and a foreign language"},"description":{"uz":"Umumiy tayyorgarlik: fanlar quyida körsatilgan rasmiy manbadan olingan. Paket biror universitet bilan rasmiy boğliq emas va uning dasturi emas.","ru":"Общая подготовка: предметы взяты из указанного ниже официального источника. Пакет официально не связан ни с одним университетом и не является его программой.","en":"General preparation: the subjects come from the official source named below. The package is not officially affiliated with any university and is not its programme."},"slots":[{"id":"prep-economics-state-s1","label":{"uz":"Majburiy fanlar: ona tili, matematika, Özbekiston tarixi","ru":"Обязательные предметы: родной язык, математика, история Узбекистана","en":"Mandatory subjects: native language, mathematics, history of Uzbekistan"},"courseKey":"c-dtm"},{"id":"prep-economics-state-s2","label":{"uz":"Matematika (yönaliş fani)","ru":"Математика (профильный предмет)","en":"Mathematics (direction subject)"},"courseKey":"c-algebra"},{"id":"prep-economics-state-s3","label":{"uz":"Çet tili (tili sahifada körsatilmagan)","ru":"Иностранный язык (язык на странице не указан)","en":"Foreign language (language not named on the page)"},"courseKey":"c-general-english"}],"admission":{"url":"https://tsue.uz/media/uploads/2026/06/17/nptqbl.pdf","academicYear":"2026/2027","checkedOn":"2026-11-03","status":"verified","note":"National 2026/2027 subject list posted by TSUE: Mathematics as the first and a foreign language as the second specialised subject for Economics, Finance, Banking, Accounting, Management, Marketing and related directions. General preparation, not a programme of one university. The list does not name the language; ILMORA maps it to English as its own choice. ILMORA has no separate economics course."},"hasSource":true},{"id":"prep-economics-english","universityId":"prep-economics","program":{"uz":"Ingliz tilidagi biznes dasturlari: matematika va IELTS","ru":"Бизнес-программы на английском: математика и IELTS","en":"English-taught business programmes: Mathematics and IELTS"},"directionIds":["prep-economics-english"],"name":{"uz":"Ingliz tilidagi biznes dasturlari: matematika va IELTS","ru":"Бизнес-программы на английском: математика и IELTS","en":"English-taught business programmes: Mathematics and IELTS"},"description":{"uz":"Umumiy tayyorgarlik: fanlar quyida körsatilgan rasmiy manbadan olingan. Paket biror universitet bilan rasmiy boğliq emas va uning dasturi emas.","ru":"Общая подготовка: предметы взяты из указанного ниже официального источника. Пакет официально не связан ни с одним университетом и не является его программой.","en":"General preparation: the subjects come from the official source named below. The package is not officially affiliated with any university and is not its programme."},"slots":[{"id":"prep-economics-english-s1","label":{"uz":"Matematika","ru":"Математика","en":"Mathematics"},"courseKey":"c-algebra"},{"id":"prep-economics-english-s2","label":{"uz":"Ingliz tili (IELTS; talab universitetga boğliq)","ru":"Английский язык (IELTS; требование зависит от университета)","en":"English (IELTS; the requirement depends on the university)"},"courseKey":"c-ielts","optional":true}],"admission":{"url":"https://wiut.uz/finance","academicYear":"2026-2027","checkedOn":"2026-11-03","status":"needs_review","note":"To be confirmed: general preparation, not a programme of one university. WIUT’s Finance, Economics and Business Management pages ask Mathematics competence and IELTS 6.5; other business programmes differ, so check yours."},"hasSource":true}]$pkn$::jsonb;
  section_old jsonb := $sco${"title":{"uz":"Universitetga tayyorgarlik","ru":"Подготовка к поступлению","en":"University preparation"},"subtitle":{"uz":"Universitet va yönalişni tanlang: kiriş fanlari böyiça kurslar bitta paketda.","ru":"Выберите университет и направление: курсы по вступительным предметам — в одном пакете.","en":"Choose a university and direction: the courses for its entrance subjects come as one package."}}$sco$::jsonb;
  section_next jsonb := $scn${"title":{"uz":"Oliy ta’limga kiriş","ru":"Поступление в вузы","en":"University Admission"},"subtitle":{"uz":"Universitet va yönalişni tanlang — ILMORA kiriş fanlari böyiça kurslarni aniq oylik narxli bitta paketga jamlaydi.","ru":"Выберите университет и направление — ILMORA соберёт курсы по вступительным предметам в один пакет с понятной ценой в месяц.","en":"Choose a university and a direction. ILMORA brings the courses for its entrance subjects into one package with a clear monthly price."}}$scn$::jsonb;
  t text;
  unis jsonb;
  presets jsonb;
  home jsonb;
  sec jsonb;
  sec_before jsonb;
  sec_pos integer;
  field text;
  u jsonb;
  uni jsonb;
  old jsonb;
  stored jsonb;
  pos integer;
  p jsonb;
  s jsonb;
  slots jsonb;
  dirs jsonb;
  cid text;
  blocking boolean;
  covered boolean;
  seen text[];
  preset jsonb;
  changed boolean := false;
  s_replaced text[] := ARRAY[]::text[];
  s_skipped text[] := ARRAY[]::text[];
  u_replaced text[] := ARRAY[]::text[];
  u_added text[] := ARRAY[]::text[];
  u_skipped text[] := ARRAY[]::text[];
  p_added text[] := ARRAY[]::text[];
  p_skipped text[] := ARRAY[]::text[];
  p_published integer := 0;
BEGIN
  SELECT "tenantId" INTO t FROM "Course" WHERE "id" = 'c-general-english' AND "deletedAt" IS NULL;
  IF t IS NULL THEN
    RAISE NOTICE 'university admission: no ILMORA catalog in this database, nothing to do';
    RETURN;
  END IF;
  SELECT COALESCE("data"->'universities', '[]'::jsonb), COALESCE("data"->'presets', '[]'::jsonb), COALESCE("data"#>'{pages,home}', '[]'::jsonb)
    INTO unis, presets, home FROM "SiteConfig" WHERE "tenantId" = t;
  IF unis IS NULL OR jsonb_typeof(unis) <> 'array' OR jsonb_typeof(presets) <> 'array' OR jsonb_typeof(home) <> 'array' THEN
    RAISE NOTICE 'university admission: no site settings with universities, packages and a homepage, nothing to do';
    RETURN;
  END IF;

  -- homepage section: each text is replaced only while it is what 20261106 wrote
  SELECT x.i - 1, x.v INTO sec_pos, sec FROM jsonb_array_elements(home) WITH ORDINALITY AS x(v, i) WHERE x.v->>'type' = 'universities' ORDER BY x.i LIMIT 1;
  sec_before := sec;
  IF sec IS NULL THEN
    s_skipped := s_skipped || 'section not on the homepage'::text;
  ELSE
    FOREACH field IN ARRAY ARRAY['title', 'subtitle'] LOOP
      IF sec->field = section_next->field THEN
        NULL;
      ELSIF sec->field = section_old->field THEN
        sec := jsonb_set(sec, ARRAY[field], section_next->field); s_replaced := s_replaced || field; changed := true;
      ELSE
        s_skipped := s_skipped || field;
      END IF;
    END LOOP;
  END IF;

  -- directions: replace what 20261110 wrote and nobody changed since; add what is missing; skip the rest
  FOR u IN SELECT x.v FROM jsonb_array_elements(uni_next) AS x(v) LOOP
    stored := NULL; pos := NULL; old := NULL;
    SELECT x.i - 1, x.v INTO pos, stored FROM jsonb_array_elements(unis) WITH ORDINALITY AS x(v, i) WHERE x.v->>'id' = u->>'id';
    SELECT x.v INTO old FROM jsonb_array_elements(uni_old) AS x(v) WHERE x.v->>'id' = u->>'id';
    IF stored IS NULL THEN
      unis := unis || jsonb_build_array(u); u_added := u_added || (u->>'id'); changed := true;
    ELSIF stored = u THEN
      NULL;
    ELSIF old IS NOT NULL AND stored = old THEN
      unis := jsonb_set(unis, ARRAY[pos::text], u); u_replaced := u_replaced || (u->>'id'); changed := true;
    ELSE
      u_skipped := u_skipped || (u->>'id');
    END IF;
  END LOOP;

  -- packages: built against this tenant's courses and the directions as they now are; an existing id is never replaced
  FOR p IN SELECT x.v FROM jsonb_array_elements(pkg_next) AS x(v) LOOP
    uni := NULL;
    SELECT x.v INTO uni FROM jsonb_array_elements(unis) AS x(v) WHERE x.v->>'id' = p->>'universityId';
    CONTINUE WHEN uni IS NULL;
    SELECT COALESCE(jsonb_agg(d.v), '[]'::jsonb) INTO dirs FROM jsonb_array_elements_text(p->'directionIds') AS d(v)
      WHERE EXISTS (
        SELECT 1 FROM jsonb_array_elements(COALESCE(uni->'faculties', '[]'::jsonb)) AS f(v), jsonb_array_elements(COALESCE(f.v->'directions', '[]'::jsonb)) AS dd(v)
        WHERE dd.v->>'id' = d.v);
    slots := '[]'::jsonb; blocking := false; covered := false; seen := ARRAY[]::text[];
    FOR s IN SELECT x.v FROM jsonb_array_elements(p->'slots') AS x(v) LOOP
      cid := NULL;
      IF s->>'courseKey' IS NOT NULL THEN
        SELECT c."id" INTO cid FROM "Course" c
          WHERE c."tenantId" = t AND c."deletedAt" IS NULL AND c."learningFormat" = 'OFFLINE'
            AND (c."id" = s->>'courseKey' OR c."slug" = regexp_replace(s->>'courseKey', '^c-', ''))
          ORDER BY (c."id" = s->>'courseKey') DESC LIMIT 1;
      END IF;
      IF cid IS NOT NULL THEN
        IF NOT EXISTS (
          SELECT 1 FROM "Course" c WHERE c."id" = cid AND c."status" = 'PUBLISHED' AND c."visibility" = 'PUBLIC'
            AND EXISTS (SELECT 1 FROM "Group" g WHERE g."courseId" = c."id" AND g."deletedAt" IS NULL)) THEN
          blocking := true;
        END IF;
        IF cid = ANY(seen) THEN blocking := true; END IF;
        seen := seen || cid;
        IF (s->>'optional')::boolean IS NOT TRUE THEN covered := true; END IF;
      END IF;
      slots := slots || jsonb_build_array(
        jsonb_build_object('id', s->'id', 'label', s->'label', 'courseId', cid)
        || CASE WHEN (s->>'optional')::boolean IS TRUE THEN '{"optional":true}'::jsonb ELSE '{}'::jsonb END);
    END LOOP;
    preset := jsonb_build_object(
      'id', p->'id', 'universityId', p->'universityId', 'program', p->'program', 'directionIds', dirs,
      'name', p->'name', 'description', p->'description', 'slots', slots, 'admission', p->'admission',
      'enabled', NOT blocking AND covered AND (p->>'hasSource')::boolean AND COALESCE((uni->>'published')::boolean, false));
    stored := NULL;
    SELECT x.v INTO stored FROM jsonb_array_elements(presets) AS x(v) WHERE x.v->>'id' = p->>'id';
    IF stored IS NULL THEN
      presets := presets || jsonb_build_array(preset); p_added := p_added || (p->>'id'); changed := true;
      IF (preset->>'enabled')::boolean THEN p_published := p_published + 1; END IF;
    ELSIF stored <> preset THEN
      p_skipped := p_skipped || (p->>'id');
    END IF;
  END LOOP;

  IF NOT changed THEN
    RAISE NOTICE 'university admission: nothing to change (skipped section texts: %, directions: %, packages: %)', s_skipped, u_skipped, p_skipped;
    RETURN;
  END IF;
  IF jsonb_array_length(presets) > 150 OR jsonb_array_length(unis) > 100 THEN
    RAISE NOTICE 'university admission: the lists would exceed the site settings limits, nothing changed';
    RETURN;
  END IF;

  BEGIN
    INSERT INTO "AuditEvent" ("id", "tenantId", "action", "entityType", "entityId", "before", "after", "reason")
    SELECT 'university-admission-20261111-SiteConfig', t, 'content.sync', 'SiteConfig', t,
      jsonb_build_object('version', "version", 'universities', "data"->'universities', 'presets', "data"->'presets', 'homeSection', sec_before),
      jsonb_build_object('sectionTextsReplaced', to_jsonb(s_replaced), 'sectionTextsSkipped', to_jsonb(s_skipped),
        'directionsReplaced', to_jsonb(u_replaced), 'directionsAdded', to_jsonb(u_added), 'directionsSkipped', to_jsonb(u_skipped),
        'packagesAdded', to_jsonb(p_added), 'packagesSkipped', to_jsonb(p_skipped), 'packagesPublished', p_published),
      'University Admission: section wording and ready-made preparation directions'
    FROM "SiteConfig" WHERE "tenantId" = t
    ON CONFLICT ("id") DO NOTHING;
    UPDATE "SiteConfig"
      SET "data" = jsonb_set(jsonb_set(CASE WHEN sec_pos IS NULL THEN "data" ELSE jsonb_set("data", ARRAY['pages', 'home', sec_pos::text], sec) END, '{universities}', unis), '{presets}', presets),
        "version" = "version" + 1, "updatedAt" = CURRENT_TIMESTAMP
      WHERE "tenantId" = t;
    RAISE NOTICE 'university admission: section texts replaced %, skipped %; directions replaced %, added %, skipped %; packages added %, skipped %, published %',
      s_replaced, s_skipped, u_replaced, u_added, u_skipped, p_added, p_skipped, p_published;
  EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'university admission failed and was rolled back: %', SQLERRM;
  END;
END
$sync$;
